function getButterflyIqTranslation(key, lang) {
    return (butterflyiqTranslations[lang] && butterflyiqTranslations[lang][key]) ||
           (butterflyiqTranslations.en && butterflyiqTranslations.en[key]) || null;
}

function applyButterflyIqTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.butterfly-iq.") || key.startsWith("review.common."))) {
            const translation = getButterflyIqTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} butterfly-iq translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyButterflyIqTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyButterflyIqTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyButterflyIqTranslations(window.i18n?.getCurrentLanguage() || "en");
}
